"""Boss-phase gathering at the last corridor castle (owner 2026-11-15)."""
from docich.hanjuku_speedrun import hanjuku_chart as chart
from docich.hanjuku_speedrun.hanjuku.strategy import replan
from docich.hanjuku_speedrun.hanjuku.state.regions import world as _world


def memory():
    castles = list(chart.castles(9))
    mem = {'chapter': 9, 'month': '9-8', 'tick': 349000,
           'captured': list(castles), 'lost': [], 'orders': {},
           'garrison': {c: [] for c in castles},
           'world': {'sorties': {}}, 'house_eggs': {},
           'general_location_unknown': []}
    return mem


def test_boss_phase_walks_the_rear_generals_toward_the_last_castle():
    # Only marches from the last corridor castle (イデ！) reach the moving boss.
    chart.set_boss_cell(9, (700, 400))
    try:
        mem = memory()
        _world(mem)['garrison']['カラ'] = ['将軍A', '将軍B']
        _world(mem)['garrison']['シマウ'] = ['将軍C', '将軍D', '将軍E']
        _world(mem)['garrison']['イソ'] = ['将軍F', '将軍G']
        orders = list(replan.interim_candidates(mem).values())
        moves = [o for o in orders if o.get("purpose") == "move"]
        assert moves
        assert any("イデ" in (o.get("note") or "") for o in moves)
        assert all(o['target'] in chart.castles(9) for o in moves)
        # The front-adjacent castle's one hop is the last castle itself: the
        # gather must not skip it (g1190 22-x: イソ kept 17 generals while
        # イデ！ stood empty).
        assert any(o['source'] == 'イソ' and o['target'] == 'イデ！' for o in moves)
        # The nearest castle's hop goes first: two generals at the last castle
        # unlock the first boss wave, so the front-adjacent イソ→イデ！ leads
        # before the far rear.
        assert (moves[0]['source'], moves[0]['target']) == ('イソ', 'イデ！')
    finally:
        chart.set_boss_cell(9, None)

def test_gathering_does_not_need_a_fresh_boss_cell():
    # The gather is valid whenever the road is complete; the boss cell is only
    # needed to aim the sortie. After a restart the in-memory cell is None but
    # the rear generals must still start walking to イデ！ (g1190 10-11: the
    # garrison stayed at カラ/シマウ because the gather required the cell).
    chart.set_boss_cell(9, None)
    mem = memory()
    _world(mem)['garrison']['カラ'] = ['将軍A', '将軍B']
    _world(mem)['garrison']['シマウ'] = ['将軍C', '将軍D', '将軍E']
    orders = list(replan.interim_candidates(mem).values())
    moves = [o for o in orders if o.get("purpose") == "move"]
    assert any("イデ" in (o.get("note") or "") for o in moves)
